import java.util.*;
public class Demo {
    public static void main(String[] args) {
        int[] marks = {90, 45, 77};
        System.out.println(marks.length);          // 3
        int[] alias = marks;                       // same array!
        alias[0] = 10;
        System.out.println(marks[0]);              // 10
        Arrays.sort(marks);
        System.out.println(Arrays.toString(marks)); // [10, 45, 77]

        int[][] g = {{1, 2, 3}, {4, 5, 6}};
        for (int r = 0; r < g.length; r++) {
            for (int c = 0; c < g[r].length; c++) System.out.print(g[r][c] + " ");
            System.out.println();
        }

        ArrayList<Integer> list = new ArrayList<>();
        list.add(5); list.add(8); list.add(1);
        list.remove(0);                            // removes INDEX 0 -> [8, 1]
        System.out.println(list.get(0) + " " + list.size()); // 8 2
        for (int n : list) System.out.println(n);
    }
}

