int[] m = {90, 45, 77, 30, 66, 58};
int sum = 0, max = m[0];
for (int x : m) { sum += x; if (x > max) max = x; }
double avg = (double) sum / m.length;
int above = 0;
for (int x : m) if (x > avg) above++;
System.out.println(avg + " " + max + " " + above);
ArrayList<Integer> list = new ArrayList<>();
for (int x : m) list.add(x);
for (int i = list.size() - 1; i >= 0; i--)
  if (list.get(i) < 50) list.remove(i);   // loop backwards when removing
System.out.println(list);
